#!/bin/bash
# Round 2 of Aqua pool registration on the v1.1 Aqua adapter (2026-08-27).
# The first round (register-aqua-pools.sh) covered the top-15 by lifetime
# volume; Aqua quoting resolves pools PER-PAIR from their API/on-chain, so
# any liquid pool between listed tokens can win a quote — and then fail
# to build (PoolNotSet) if unregistered. This registers the stragglers,
# headlined by the new ~$1.9M USDY/USDC pool (absent from Aqua's
# paginated API — found via the on-chain router; it broke deJAAA→USDY).
# v1.2's on-chain auto-resolver retires this ceremony entirely.
# Idempotent. Run: bash scripts/register-aqua-pools-2.sh
set -e
ADAPTER="CCTL6C4PYDTXT6GL5YTE6CG4ZH2EXKJONUP4445SMTY5AYQPNQY666HZ"
SRC="mainnet-deployer"
NET="mainnet"
FEE=1000000
# NOTE: single-line command — backslash continuations break under CRLF.
reg() {
  stellar contract invoke --fee ${FEE} --id ${ADAPTER} --source ${SRC} --network ${NET} -- set_pool --token_a "$1" --token_b "$2" --tokens "[\"$1\",\"$2\"]" --pool_hash "$3" --pool_address "$4" >/dev/null 2>&1 && echo " OK $5" || echo " FAILED $5"
}

